import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    # Parse the JSON string
    data = json.loads(json_str)
    # Function to recursively process the data
    def process_item(item):
        if isinstance(item, dict):
            # Create a new dictionary without None values and process each value
            new_dict = {}
            for key, value in item.items():
                if value is not None:
                    processed_value = process_item(value)
                    new_dict[key] = processed_value
            return new_dict
        elif isinstance(item, list):
            # Create a new list without None values and process each item
            new_list = []
            for value in item:
                if value is not None:
                    processed_value = process_item(value)
                    new_list.append(processed_value)
            return new_list
        elif isinstance(item, str):
            # Replace email addresses with the placeholder
            email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
            return re.sub(email_pattern, REPLACE_NONE, item)
        else:
            return item
    # Process the data to remove None values and replace emails
    processed_data = process_item(data)
    # Flatten the processed data to collect all values for counting
    values_list = []
    def flatten(item):
        if isinstance(item, dict):
            for value in item.values():
                flatten(value)
        elif isinstance(item, list):
            for value in item:
                flatten(value)
        else:
            values_list.append(item)
    flatten(processed_data)
    # Count the frequency of each unique value
    value_counts = Counter(values_list)
    # Return the results
    return {
        "data": processed_data,
        "value_counts": value_counts
    }

